export function searchUniversities(query: string, limit = 8): UniversityItem[] {
  if (!query || !query.trim()) {
    return UNIVERSITIES.slice(0, limit);
  }
  const q = query.toLowerCase().trim();
  return UNIVERSITIES.filter((uni) => {
    if (uni.name.toLowerCase().includes(q)) return true;
    if (uni.domain.toLowerCase().includes(q)) return true;
    if (uni.aliases && uni.aliases.some((a) => a.toLowerCase().includes(q))) return true;
    if (uni.state && uni.state.toLowerCase().includes(q)) return true;
    return false;
  }).slice(0, limit);
}

export function findUniversityByName(name: string): UniversityItem | undefined {
  if (!name) return undefined;
  const lower = name.toLowerCase().trim();
  return UNIVERSITIES.find(
    (u) =>
      u.name.toLowerCase() === lower ||
      u.aliases?.some((a) => a.toLowerCase() === lower) ||
      u.name.toLowerCase().includes(lower) ||
      lower.includes(u.name.toLowerCase())
  );
}
